// level → cumulative cost/time helpers
export function levelCost(b, from, to) {
  const c = { wood: 0, stone: 0, iron: 0, food: 0, gold: 0 }; let time = 0;
  for (let l = Math.max(1, from + 1); l <= Math.min(to, b.max); l++) {
    for (const k in b.cost) c[k] += b.cost[k][l - 1] || 0;
    time += b.time[l - 1] || 0;
  }
  return { cost: c, time };
}
